MOD = 998244353


def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a, modulo MOD."""
    limit = 3 * n + 5
    fact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (limit + 1)
    inv_fact[limit] = pow(fact[limit], MOD - 2, MOD)
    for i in range(limit, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(top: int, bottom: int) -> int:
        if bottom < 0 or bottom > top:
            return 0
        return fact[top] * inv_fact[bottom] % MOD * inv_fact[top - bottom] % MOD

    def forest_sum(lo: int, hi: int, nodes: int) -> int:
        """Sum forest counts for root counts in [lo, hi]."""
        if lo > hi:
            return 0
        return (comb(2 * nodes + hi, nodes + 1)
                - comb(2 * nodes + lo - 1, nodes + 1)
                - comb(2 * nodes + hi, nodes)
                + comb(2 * nodes + lo - 1, nodes)) % MOD

    answer = 0
    pending = 1
    prefix_valid = True
    for i, bound in enumerate(a):
        remaining = n - i - 1
        if remaining == 0:
            needed = 1 - pending
            if 0 <= needed < bound:
                answer += 1
        else:
            lo = max(0, 2 - pending)
            hi = min(bound - 1, remaining - pending + 1)
            if lo <= hi:
                answer += forest_sum(pending + lo - 1, pending + hi - 1, remaining)

        next_pending = pending + bound - 1
        if next_pending <= 0:
            if not (remaining == 0 and next_pending == 0):
                prefix_valid = False
                break
        if remaining and next_pending > remaining:
            prefix_valid = False
            break
        pending = next_pending
    if prefix_valid and pending == 0:
        answer += 1
    return answer % MOD

