from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Find the minimum cost of covering every section with the two sensor types."""
    if n != len(sections):
        return -1
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    # State is the total number of each sensor type used so far.
    dp = {(0, 0): 0}
    for distance in sections:
        choices = []
        for a in range(min(k1, (distance + l1 - 1) // l1) + 1):
            rem = max(0, distance - a * l1)
            b = (rem + l2 - 1) // l2
            if b <= k2:
                choices.append((a, b, a * c1 + b * c2))
        nxt = {}
        for (used1, used2), cost in dp.items():
            for a, b, added in choices:
                x, y = used1 + a, used2 + b
                if x <= k1 and y <= k2:
                    key = (x, y)
                    value = cost + added
                    if value < nxt.get(key, float("inf")):
                        nxt[key] = value
        dp = nxt
        if not dp:
            return -1
    return min(dp.values()) if dp else -1

