from typing import List, Tuple

def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki play cards optimally."""
    from functools import lru_cache

    @lru_cache(None)
    def win(turn, hand0, hand1, table):
        hands = (hand0, hand1)
        if not hands[turn]:
            return False
        hand = hands[turn]
        for i, card in enumerate(hand):
            next_hands = [hand0, hand1]
            next_hands[turn] = hand[:i] + hand[i + 1:]
            base = tuple(sorted(table + (card,)))
            if not win(1 - turn, next_hands[0], next_hands[1], base):
                return True
            for j, old in enumerate(base):
                if old < card and not win(1 - turn, next_hands[0], next_hands[1], base[:j] + base[j + 1:]):
                    return True
        return False

    result = win(0, tuple(sorted(takahashi_cards)), tuple(sorted(aoki_cards)), tuple(sorted(table_cards)))
    return "Takahashi" if result else "Aoki"

