def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding walks of K moves, with any empty starting cell."""
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == "."]
    index = {cell: i for i, cell in enumerate(cells)}
    adj = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            j = index.get((nr, nc))
            if j is not None:
                adj[i].append(j)

    total = 0

    def dfs(v: int, remaining: int, visited: int) -> None:
        nonlocal total
        if remaining == 0:
            total += 1
            return
        for nxt in adj[v]:
            bit = 1 << nxt
            if not visited & bit:
                dfs(nxt, remaining - 1, visited | bit)

    for i in range(len(cells)):
        dfs(i, K, 1 << i)
    return total

