from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if n < 0 or n > len(tiles):
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles[:n]]

    # placements[i] maps each cell to the tile placements containing that cell.
    placements = [[] for _ in range(n)]
    for i, (a, b) in enumerate(tiles[:n]):
        orientations = {(a, b), (b, a)}
        for ph, pw in orientations:
            if ph > h or pw > w:
                continue
            for r in range(h - ph + 1):
                for c in range(w - pw + 1):
                    mask = 0
                    for rr in range(r, r + ph):
                        mask |= ((1 << pw) - 1) << (rr * w + c)
                    # Index by cells so search can branch on the first uncovered cell.
                    for rr in range(r, r + ph):
                        for cc in range(c, c + pw):
                            cell = rr * w + cc
                            placements[i].append((cell, mask))

    by_cell = [[] for _ in range(h * w)]
    for i in range(n):
        for cell, mask in placements[i]:
            by_cell[cell].append((i, mask))

    memo = set()

    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        key = (occupied, used)
        if key in memo:
            return False
        memo.add(key)

        remaining = full ^ occupied
        if sum(areas[i] for i in range(n) if not (used >> i) & 1) < remaining.bit_count():
            return False

        # The first empty cell forces all placements to extend from this position
        # without gaps, while preserving completeness for rectangular tilings.
        first_bit = remaining & -remaining
        cell = first_bit.bit_length() - 1
        for i, mask in by_cell[cell]:
            if not (used >> i) & 1 and not (mask & occupied):
                if search(occupied | mask, used | (1 << i)):
                    return True
        return False

    return search(0, 0)

