    def count_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        length = len(digits)
        total = 0

        for target_sum in range(1, 9 * length + 1):
            @lru_cache(None)
            def dp(pos: int, digit_sum: int, product_mod: int,
                   started: bool, tight: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                if pos == length:
                    return int(started and digit_sum == target_sum and product_mod == 0)

                limit = digits[pos] if tight else 9
                ways = 0
                for digit in range(limit + 1):
                    next_tight = tight and digit == limit
                    if not started and digit == 0:
                        ways += dp(pos + 1, digit_sum, product_mod, False, next_tight)
                    else:
                        new_sum = digit_sum + digit
                        if new_sum <= target_sum:
                            new_mod = (product_mod * digit) % target_sum
                            ways += dp(pos + 1, new_sum, new_mod, True, next_tight)
                return ways

            total += dp(0, 0, 1 % target_sum, False, True)
        return total

    return count_to(r) - count_to(l - 1)

