        a = max(lower, 0)
        total = pi1(x) - (pi1(a) if a else 0)
        if not bad:
            total += pi2(x) - (pi2(a) if a else 0)
        if a < 3 <= x:
            total += 1
        return total * M

    def local_weight(p, e, bad):
        if bad:
            if p == 3:
                pass
            elif p % 3 == 1:
                if (e + 1) % 3 == 0:
                    return 0
            elif e % 2:
                return 0
